          "claim": "GetProduct server spans over 1 s rose to 22 of 164 from 13 of 176, while p50 stays near 0.9 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT s.trace_id, round(s.duration/1e6,1) server_ms, round(coalesce((SELECT sum(c.duration) FROM abnormal_traces c WHERE c.parent_span_id=s.span_id),0)/1e6,2) child_ms FROM abnormal_traces s WHERE s.service_name='product-catalog' AND s.span_name='oteldemo.ProductCatalogService/GetProduct' AND s.attr_span_kind='Server' AND s.duration>1e9",
          "claim": "Slow GetProduct server spans run about 130 s but have under 1 ms of child span time, so time is inside the handler."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, span_name, count(*) n, sum(CASE WHEN duration>1e9 THEN 1 ELSE 0 END) gt1s FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND span_name='GET /api/products/[productId]/index' GROUP BY ALL UNION ALL SELECT 'norm', span_name, count(*), sum(CASE WHEN duration>1e9 THEN 1 ELSE 0 END) FROM normal_traces WHERE service_name='frontend' AND attr_span_kind='Server' AND span_name='GET /api/products/[productId]/index' GROUP BY ALL",
          "claim": "User product-page requests over 1 s rose to 15 of 81 in the abnormal period from 4 of 80 normal."
        }
      ]
    },
    {
      "service": "payment",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE span_name IN ('oteldemo.PaymentService/Charge','grpc.oteldemo.PaymentService/Charge') GROUP BY ALL UNION ALL SELECT 'norm', service_name, span_name, attr_span_kind, count(*), round(quantile_cont(duration,0.5)/1e6,1) FROM normal_traces WHERE span_name IN ('oteldemo.PaymentService/Charge','grpc.oteldemo.PaymentService/Charge') GROUP BY ALL",
          "claim": "Checkout's Charge client p50 rose to 442 ms from 2.6 ms, while payment's server Charge stays near 1.2 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, round(duration/1e6,2) ms, trace_id FROM abnormal_traces WHERE trace_id IN (SELECT trace_id FROM abnormal_traces WHERE span_name='oteldemo.PaymentService/Charge' LIMIT 1) ORDER BY ms DESC",
          "claim": "In one Charge trace, checkout's client span takes 442 ms while payment's server span takes 1.2 ms and its internal charge takes 0.9 ms."
        }
      ]
    }
  ],
  "propagation": [
