          "claim": "Frontend's GetProduct client spans match product-catalog's ~130 s server spans in the same traces."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, sum(CASE WHEN duration>1e9 THEN 1 ELSE 0 END) gt1s FROM abnormal_traces WHERE service_name='frontend-proxy' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "frontend-proxy ingress shows 48 of 218 requests over 1 s, mirroring the frontend's slow product-page requests."
        }
      ]
    },
    {
      "from": "payment",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, service_name, span_name, count(*) n, round(quantile_cont(duration,0.5)/1e6,1) p50_ms FROM abnormal_traces WHERE service_name='checkout' AND span_name='oteldemo.PaymentService/Charge' GROUP BY ALL UNION ALL SELECT 'norm', service_name, span_name, count(*), round(quantile_cont(duration,0.5)/1e6,1) FROM normal_traces WHERE service_name='checkout' AND span_name='oteldemo.PaymentService/Charge' GROUP BY ALL",
          "claim": "Checkout's payment calls take 442 ms in the abnormal window, against 2.6 ms normally, while payment's own work is unchanged."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' p, f.span_name, count(*) n FROM abnormal_traces f WHERE f.service_name='frontend' AND f.attr_span_kind='Server' AND f.trace_id IN (SELECT trace_id FROM abnormal_traces WHERE service_name='checkout') GROUP BY ALL",
          "claim": "Frontend POST server spans sit in traces that include checkout spans, so checkout's slowed calls sit on the frontend request path."
        }
      ]
    }
  ]
}
